function renderTransitEssayUi(){
  if(!transitEssayUi.block) return;
  const eligible=transitEssayEligible();
  transitEssayUi.block.hidden=!eligible;
  if(transitEssayUi.label) transitEssayUi.label.textContent=T('transitEssayButton',"TODAY'S SKY NOTE");
  if(!eligible){
    if(transitEssayUi.button){ transitEssayUi.button.disabled=true; transitEssayUi.button.classList.remove('ready'); transitEssayUi.button.removeAttribute('aria-busy'); }
    if(transitEssayUi.status) transitEssayUi.status.textContent='';
    return;
  }
  const ready=_transitEssayPhase==='ready'&&_transitEssay&&_transitEssay.status==='ready';
  const canRetry=_transitEssayPhase==='unavailable'||_transitEssayPhase==='hidden';
  if(transitEssayUi.button){
    // Ready → open reader. Unavailable → click retries enqueue (helps after a failed server day).
    transitEssayUi.button.disabled=!(ready||canRetry)||_transitEssayPhase==='pending';
    transitEssayUi.button.classList.toggle('ready',ready);
    if(_transitEssayPhase==='pending') transitEssayUi.button.setAttribute('aria-busy','true'); else transitEssayUi.button.removeAttribute('aria-busy');
  }
  if(transitEssayUi.status){
    transitEssayUi.status.textContent=_transitEssayPhase==='pending'
      ? T('transitEssayPending',"WRITING TODAY'S NOTE…")
      : ready
        ? T('transitEssayReady','SKY NOTE READY')
        : _transitEssayPhase==='unavailable'
          ? T('transitEssayUnavailable','NOTE UNAVAILABLE · TAP TO RETRY')
          : '';
  }
}
function transitEssayReset(){
  ++_transitEssaySeq; transitEssayClearPollTimer(); _transitEssayActive=false; _transitEssayInFlightSeq=0;
  _transitEssay=null; _transitEssayPhase='hidden'; _transitEssayPollStep=0; _transitEssayStartedAt=0; _transitEssayFlowUser=''; _transitEssayActivationKey=''; _transitEssayNoneRequeued=false; _transitEssayPendingToast=null;
  closeTransitEssayReader(false); transitEssayClearReader(); renderTransitEssayUi();
}
function transitEssayFinishUnavailable(){
  transitEssayClearPollTimer(); _transitEssayActive=false; _transitEssay=null; _transitEssayPhase='unavailable'; _transitEssayPendingToast=null; closeTransitEssayReader(false); transitEssayClearReader(); renderTransitEssayUi();
}
function transitEssayFlushReadyToast(){
  const pending=_transitEssayPendingToast;
  if(!pending||document.hidden||_transitEssayPhase!=='ready'||!transitEssayEligible()) return;
  _transitEssayPendingToast=null;
  if(_transitEssayToastKeys.has(pending)) return;
  _transitEssayToastKeys.add(pending); cancelSkyLinkedToast(); showGhostToast('SKY NOTE READY');
}
function transitEssayQueueReadyToast(record){
  const key=_transitEssayActivationKey+'|'+record.cache_date;
  if(_transitEssayToastKeys.has(key)) return;
  _transitEssayPendingToast=key; transitEssayFlushReadyToast();
}
function transitEssayStillCurrent(seq){
  return seq===_transitEssaySeq&&_transitEssayActive&&_transitEssayFlowUser===_skyAuthUser&&transitEssayEligible();
}
function transitEssaySchedulePoll(seq){
  if(!transitEssayStillCurrent(seq)||_transitEssayPhase!=='pending') return;
  transitEssayClearPollTimer();
  const remaining=TRANSIT_ESSAY_MAX_MS-(Date.now()-_transitEssayStartedAt);
  if(remaining<=0){ transitEssayFinishUnavailable(); return; }
  if(document.hidden) return;
  const delay=Math.min(remaining,TRANSIT_ESSAY_POLL_DELAYS[Math.min(_transitEssayPollStep,TRANSIT_ESSAY_POLL_DELAYS.length-1)]);
  _transitEssayPollStep+=1;
  _transitEssayPollTimer=setTimeout(()=>{ _transitEssayPollTimer=null; transitEssayRequest(seq,false); },delay);
}
function transitEssayHandleResponse(record,seq){
  if(!transitEssayStillCurrent(seq)) return null;
  if(record.status==='ready'){
    transitEssayClearPollTimer(); _transitEssayActive=false; _transitEssay=record; _transitEssayPhase='ready'; renderTransitEssayUi(); transitEssayQueueReadyToast(record); return null;
  }
  if(record.status==='pending'){
    _transitEssay=record; _transitEssayPhase='pending'; renderTransitEssayUi(); transitEssaySchedulePoll(seq); return null;
  }
  if(record.status==='none'&&!_transitEssayNoneRequeued){
    _transitEssayNoneRequeued=true; _transitEssay=null; _transitEssayPhase='pending'; renderTransitEssayUi(); return 'enqueue';
  }
  // failed / unavailable / unexpected → soft stop (user can retry next session/day)
  transitEssayFinishUnavailable(); return null;
}
async function transitEssayRequest(seq,enqueue){
  if(!transitEssayStillCurrent(seq)||_transitEssayInFlightSeq===seq) return;
  if(Date.now()-_transitEssayStartedAt>=TRANSIT_ESSAY_MAX_MS){ transitEssayFinishUnavailable(); return; }
  if(!enqueue&&document.hidden){ transitEssaySchedulePoll(seq); return; }
  const ctl=_skyProfileController; if(!ctl) return;
  _transitEssayInFlightSeq=seq; let followup=null;
  try{
    const record=await (enqueue?ctl.enqueueTransitEssay():ctl.getTransitEssay());
    followup=transitEssayHandleResponse(record,seq);
  }catch(error){
    if(transitEssayStillCurrent(seq)){
      if(Date.now()-_transitEssayStartedAt>=TRANSIT_ESSAY_MAX_MS||!(error&&error.retryable)) transitEssayFinishUnavailable();
      else { _transitEssayPhase='pending'; renderTransitEssayUi(); transitEssaySchedulePoll(seq); }
    }
  }finally{ if(_transitEssayInFlightSeq===seq) _transitEssayInFlightSeq=0; }
  if(followup==='enqueue'&&transitEssayStillCurrent(seq)) transitEssayRequest(seq,true);
}
function startTransitEssayFlow(force){
  const ctl=_skyProfileController;
  if(!transitEssayEligible()||!ctl||typeof ctl.enqueueTransitEssay!=='function'||typeof ctl.getTransitEssay!=='function'){ renderTransitEssayUi(); return; }
  const activation=_skyAuthUser+'|'+String(ctl.state.generation);
  // force=true (manual retry from the pause button) ignores the one-shot activation key
  if(!force&&_transitEssayActivationKey===activation&&(_transitEssayPhase==='pending'||_transitEssayPhase==='ready')) return;
  ++_transitEssaySeq; transitEssayClearPollTimer(); closeTransitEssayReader(false); transitEssayClearReader();
  _transitEssay=null; _transitEssayPhase='pending'; _transitEssayPollStep=0; _transitEssayStartedAt=Date.now(); _transitEssayActive=true; _transitEssayInFlightSeq=0;
  _transitEssayFlowUser=_skyAuthUser; _transitEssayActivationKey=activation; _transitEssayNoneRequeued=false; _transitEssayPendingToast=null;
  const seq=_transitEssaySeq; renderTransitEssayUi(); transitEssayRequest(seq,true);
}
