function skyDefaultTz(){ return deviceSkyTimezone(); }
const SKY_TZ_OPTIONS=[
  'UTC',
  'America/New_York','America/Chicago','America/Denver','America/Los_Angeles','America/Anchorage','Pacific/Honolulu',
  'America/Toronto','America/Vancouver','America/Mexico_City','America/Sao_Paulo','America/Argentina/Buenos_Aires',
  'Europe/London','Europe/Dublin','Europe/Paris','Europe/Berlin','Europe/Madrid','Europe/Rome','Europe/Amsterdam',
  'Europe/Warsaw','Europe/Athens','Europe/Istanbul','Europe/Moscow',
  'Africa/Cairo','Africa/Johannesburg','Africa/Lagos','Africa/Nairobi',
  'Asia/Dubai','Asia/Kolkata','Asia/Bangkok','Asia/Singapore','Asia/Hong_Kong','Asia/Shanghai','Asia/Tokyo','Asia/Seoul',
  'Australia/Perth','Australia/Sydney','Pacific/Auckland'
];
function skyEnsureTzOption(value){
  if(!skySave.tz||typeof value!=='string'||!value) return;
  const exists=[].some.call(skySave.tz.options,opt=>opt.value===value);
  if(!exists){ const opt=document.createElement('option'); opt.value=value; opt.textContent=value; skySave.tz.appendChild(opt); }
}
function skyPopulateTzSelect(){
  if(!skySave.tz||skySave.tz.tagName!=='SELECT'||skySave.tz.dataset.ready==='1') return;
  const preferred=skyDefaultTz();
  const zones=SKY_TZ_OPTIONS.slice();
  if(preferred&&zones.indexOf(preferred)<0) zones.unshift(preferred);
  skySave.tz.innerHTML='';
  const blank=document.createElement('option'); blank.value=''; blank.textContent='Select timezone…'; skySave.tz.appendChild(blank);
  for(const z of zones){ const opt=document.createElement('option'); opt.value=z; opt.textContent=z===preferred?(z+' · device'):z; skySave.tz.appendChild(opt); }
  skySave.tz.dataset.ready='1';
  if(preferred) skySave.tz.value=preferred;
}
function skySetTzValue(value){
  skyPopulateTzSelect();
  const next=(typeof value==='string'&&value.trim())?value.trim():skyDefaultTz();
  skyEnsureTzOption(next);
  if(skySave.tz) skySave.tz.value=next;
}
function skySyncTimeUnknown(){ if(!skySave.time||!skySave.unknown) return; skySave.time.disabled=skySave.unknown.checked; skySave.time.required=!skySave.unknown.checked; }
function skySyncCoordinatePair(){
  if(!skySave.lat||!skySave.lon) return; const any=skySave.lat.value.trim()!==''||skySave.lon.value.trim()!=='';
  skySave.lat.required=any; skySave.lon.required=any; skySave.lat.setCustomValidity(''); skySave.lon.setCustomValidity('');
  if(any&&skySave.lat.value.trim()==='') skySave.lat.setCustomValidity(T('saveSkyBothCoords','Add both latitude and longitude'));
  if(any&&skySave.lon.value.trim()==='') skySave.lon.setCustomValidity(T('saveSkyBothCoords','Add both latitude and longitude'));
}
function skyClearForm(){
  if(!skySave.form) return; skySave.form.reset(); _skyFormDirty=false; skySetTzValue(skyDefaultTz()); skySyncTimeUnknown(); skySyncCoordinatePair();
}
function skyFillForm(profile,force){
  if(!profile||!skySave.form||(_skyFormDirty&&!force)) return;
  skySave.date.value=typeof profile.birth_date==='string'?profile.birth_date:'';
  skySave.time.value=typeof profile.birth_time==='string'?profile.birth_time.slice(0,5):'';
  skySave.unknown.checked=profile.time_unknown===true;
  skySetTzValue(typeof profile.tz==='string'&&profile.tz?profile.tz:skyDefaultTz());
  skySave.place.value=typeof profile.place_label==='string'?profile.place_label:'';
  skySave.lat.value=profile.lat==null?'':String(profile.lat); skySave.lon.value=profile.lon==null?'':String(profile.lon);
  _skyFormDirty=false; skySyncTimeUnknown(); skySyncCoordinatePair();
}
function skyChartHasSaved(){
  const ctl=_skyProfileController;
  return !!(_personalListenExpected||(ctl&&ctl.state&&ctl.state.hasChart));
}
function skyChartSummaryLine(profile){
  if(!profile) return T('saveSkySaved','CHART SAVED');
  const parts=[];
  if(typeof profile.birth_date==='string'&&profile.birth_date) parts.push(profile.birth_date);
  if(profile.time_unknown===true) parts.push(T('saveSkyUnknown','TIME UNKNOWN'));
  else if(typeof profile.birth_time==='string'&&profile.birth_time) parts.push(String(profile.birth_time).slice(0,5));
  if(typeof profile.tz==='string'&&profile.tz) parts.push(profile.tz);
  if(typeof profile.place_label==='string'&&profile.place_label.trim()) parts.push(profile.place_label.trim());
  return parts.length?parts.join(' · '):T('saveSkySaved','CHART SAVED');
}
function skyRenderAccount(keepStatus){
  if(!skySave.details){ renderSkyChatUi(); return; }
  const signedIn=!!(_skyAuthSession&&_skyAuthSession.access_token);
  const hasChart=signedIn&&skyChartHasSaved();
  if(!signedIn||!hasChart) _skyChartEditing=false;
  if(skySave.authView) skySave.authView.hidden=signedIn;
  if(skySave.profileView) skySave.profileView.hidden=!signedIn;
  if(skySave.account){ const u=_skyAuthSession&&_skyAuthSession.user; skySave.account.textContent=(u&&typeof u.email==='string'&&u.email)||T('saveSkySignedIn','SIGNED IN'); }
  // Saved chart: one summary line until EDIT / NEW opens the fields.
  const collapsed=hasChart&&!_skyChartEditing;
  if(skySave.summary) skySave.summary.hidden=!collapsed;
  if(skySave.formWrap) skySave.formWrap.hidden=collapsed;
  if(skySave.summaryLine&&collapsed){
    const profile=_skyProfileController&&_skyProfileController.state&&_skyProfileController.state.profile;
    skySave.summaryLine.textContent=skyChartSummaryLine(profile);
  }
  if(skySave.cancelEdit) skySave.cancelEdit.hidden=!(_skyChartEditing&&hasChart);
  if(skySave.clear) skySave.clear.disabled=!hasChart;
  if(!keepStatus&&!_skyUiBusy){
    skySetStatus(!signedIn?'':(_remotePersonalSky?T('saveSkyLinked','SKY LINKED'):hasChart?(SKY_MODE==='decorative'?T('saveSkyDecorative','CHART SAVED · DECORATIVE SKY ON'):T('saveSkySaved','CHART SAVED')):T('saveSkyNoChart','SIGNED IN · NO CHART SAVED')),false);
  }
  renderSkyChatUi();
}
function skyBeginChartEdit(mode){
  if(_skyUiBusy) return;
  const ctl=_skyProfileController, profile=ctl&&ctl.state&&ctl.state.profile;
  _skyChartEditing=true;
  if(mode==='new'){ skyClearForm(); }
  else if(profile) skyFillForm(profile,true);
  skyRenderAccount(true);
  try{
    requestAnimationFrame(()=>{
      if(skySave.formWrap) skySave.formWrap.scrollIntoView({block:'nearest',inline:'nearest',behavior:reduceMotion?'auto':'smooth'});
      if(skySave.date) skySave.date.focus();
    });
  }catch(e){}
}
function skyCancelChartEdit(){
  if(_skyUiBusy) return;
  const ctl=_skyProfileController, profile=ctl&&ctl.state&&ctl.state.profile;
  _skyChartEditing=false; _skyFormDirty=false;
  if(profile) skyFillForm(profile,true);
  skyRenderAccount(true);
}
function skySoftFailure(error,action){
  const code=error&&error.code, status=error&&error.status;
  const detail=(error&&typeof error.message==='string')?error.message.trim():'';
  const usableDetail=detail&&detail.length<=140&&!/^personal sky/i.test(detail)&&!/^check date/i.test(detail);
  // Prefer the real validation/API detail so free-text timezone mistakes aren't a mystery.
  if(code==='validation'||status===400||status===422){
    if(usableDetail) return detail.toUpperCase();
    return T('saveSkyCheckFields','CHECK DATE, TIME, TIMEZONE & PLACE');
  }
  if(code==='not_authenticated'||status===401||status===403) return T('saveSkyExpired','SKY LINK EXPIRED · SIGN IN AGAIN');
  if(usableDetail&&(status===503||code==='service_unavailable'||/natal backend/i.test(detail))) return detail.toUpperCase();
  return action==='link'?T('saveSkyLinkFailed','SKY LINK COULD NOT SEND'):action==='clear'?T('saveSkyClearFailed','CHART COULD NOT CLEAR'):T('saveSkyUnavailable','PERSONAL SKY UNAVAILABLE');
}
function ensureSkyProfileController(){
  if(_skyProfileController) return _skyProfileController;
  if(!CFG.saveMySky||!PERSONAL_API_BASE||!window.AimDojoSaveMySky) return null;
  try{ _skyProfileController=window.AimDojoSaveMySky.createPersonalSkyController({baseUrl:PERSONAL_API_BASE,timeoutMs:CFG.skyListen.apiMs,getAccessToken:()=>_skyAuthSession&&_skyAuthSession.access_token}); }
  catch(e){ _skyProfileController=null; }
  return _skyProfileController;
}
function skyApplyControllerState(state,announce){
  if(!state) return false;
  if(announce) skyChatReset();
  _personalListenExpected=!!state.hasChart;
  if(state.hasChart) _skyChartEditing=false;
  if(state.profile) skyFillForm(state.profile,announce||state.hasChart);
  let linked=false; if(state.personalMode&&state.pack) linked=linkRemotePersonalSky(state.pack);
  skyRenderAccount(true);
  if(announce){
    if(linked){ const toastTicket=_skyUiSeq; cancelSkyLinkedToast(); skySetStatus(T('saveSkySavedLinked','CHART SAVED · SKY LINKED'),false); showGhostToast('CHART SAVED'); _skyLinkedToastTimer=setTimeout(()=>{ _skyLinkedToastTimer=null; if(toastTicket===_skyUiSeq&&_remotePersonalSky) showGhostToast('SKY LINKED'); },950); }
    else if(state.hasChart){ skySetStatus(SKY_MODE==='decorative'?T('saveSkyDecorative','CHART SAVED · DECORATIVE SKY ON'):T('saveSkySavedUnavailable','CHART SAVED · PERSONAL SKY UNAVAILABLE'),false); showGhostToast('CHART SAVED'); }
  }
  if(state.hasChart){ startTransitEssayFlow(); fetchSkyBriefForPause(); }
  else { skyChatReset(); transitEssayReset(); skyBriefReset(); }
  return linked;
}
async function skyLoadSavedProfile(ticket){
  const ctl=ensureSkyProfileController(); if(!ctl||ticket!==_skyUiSeq||!_skyAuthSession) return;
  skySetStatus(T('saveSkyChecking','CHECKING SAVED SKY…'),true);
  try{
    const pending=ctl.load(); renderSkyBriefUi(); const state=await pending; if(ticket!==_skyUiSeq) return;
    _personalListenExpected=!!state.hasChart; if(state.hasChart) skyApplyControllerState(state,false); else { skyChatReset(); transitEssayReset(); skyBriefReset(); if(_chartPackRank>=2) downgradePersonalSky(); skyClearForm(); }
    skySetStatus(_remotePersonalSky?T('saveSkyLinked','SKY LINKED'):state.hasChart?(SKY_MODE==='decorative'?T('saveSkyDecorative','CHART SAVED · DECORATIVE SKY ON'):T('saveSkySavedUnavailable','CHART SAVED · PERSONAL SKY UNAVAILABLE')):T('saveSkyNoChart','SIGNED IN · NO CHART SAVED'),false);
    skyRenderAccount(true);
  }catch(error){
    if(ticket!==_skyUiSeq) return; const state=ctl.state;
    if(state&&state.hasChart){ _personalListenExpected=true; if(_chartPackRank>=2) downgradePersonalSky(); if(_lsn&&_lsn.cache) _lsn.cache.clear(); if(state.profile) skyFillForm(state.profile,false); skySetStatus(SKY_MODE==='decorative'?T('saveSkyDecorative','CHART SAVED · DECORATIVE SKY ON'):T('saveSkySavedUnavailable','CHART SAVED · PERSONAL SKY UNAVAILABLE'),false); startTransitEssayFlow(); fetchSkyBriefForPause(); }
    else { skyChatReset(); skyBriefReset(); skySetStatus(skySoftFailure(error,'load'),false); }
    skyRenderAccount(true);
  }
}
function skyHandleSession(session){   // called outside Supabase's auth callback (current supabase-js callbacks must stay synchronous)
  const ctl=ensureSkyProfileController(), next=session&&session.user?String(session.user.id||''):'';
  if(!ctl){ skySetStatus(T('saveSkyNotConfigured','SAVE MY SKY IS NOT CONFIGURED'),false); return; }
  if(_skyAuthUser!==next) skySetStatus('',false);   // cancel a busy save/load surface when auth switches or signs out
  if(_skyAuthUser&&_skyAuthUser!==next){ ctl.setAuthenticated(false); _personalListenExpected=false; skyBriefReset(); if(_chartPackRank>=2) downgradePersonalSky(); }
  _skyAuthUser=next;
  if(!next){ ++_skyUiSeq; _skyProfileUser=''; ctl.setAuthenticated(false); _personalListenExpected=false; _skyChartEditing=false; skyChatReset(); transitEssayReset(); skyBriefReset(); skyClearForm(); skyRenderAccount(false); return; }   // initial guest resolution preserves an explicitly requested legacy local/drop-in chart; real sign-out was quarantined synchronously above
  ctl.setAuthenticated(true); skyRenderAccount(true);
  if(_skyProfileUser!==next){ _skyProfileUser=next; _cloudPrefsLoaded=false; const ticket=++_skyUiSeq; skyLoadSavedProfile(ticket); loadCloudPrefs(); }
  else if(!_cloudPrefsLoaded) loadCloudPrefs();
}
function skyAcceptAuthSession(session){   // synchronous account quarantine; no async Supabase call inside onAuthStateChange
  session=session||null; const next=session&&session.user?String(session.user.id||''):'';
  if(next!==_skyAuthUser){
    ++_skyUiSeq; cancelSkyLinkedToast(); skyChatReset(); transitEssayReset(); skyBriefReset(); skySetStatus('',false); const ctl=ensureSkyProfileController(); if(ctl) ctl.setAuthenticated(false);
    _personalListenExpected=false; _skyChartEditing=false; try{ clearListen(true); }catch(e){} if(_lsn&&_lsn.cache) _lsn.cache.clear(); if(_chartPackRank>=2) downgradePersonalSky();
    _skyProfileUser=''; _skyAuthUser=next; if(skySave.email) skySave.email.value=''; skyClearForm();
  }
  _skyAuthSession=session; skyRenderAccount(true); renderSkyBriefUi();
  const authTicket=++_skyAuthEventSeq; setTimeout(()=>{ if(authTicket===_skyAuthEventSeq) skyHandleSession(session); },0);
}
async function initSaveMySky(){
  if(!skySave.details) return;
  if(!CFG.saveMySky){ skySave.details.hidden=true; return; }
  skyPopulateTzSelect(); skyClearForm(); skyRenderAccount(true);
  if(!ensureSkyProfileController()||!SUPABASE_AUTH_URL||typeof CFG.supabaseAnonKey!=='string'||!CFG.supabaseAnonKey){ skySetStatus(T('saveSkyNotConfigured','SAVE MY SKY IS NOT CONFIGURED'),false); return; }
  if(location.protocol!=='http:'&&location.protocol!=='https:'){ skySetStatus(T('saveSkyNeedsWeb','SAVE MY SKY NEEDS HTTP(S) · PLAY STILL WORKS'),false); return; }
  try{
    await loadScriptOnce(SUPABASE_JS); if(!window.supabase) throw new Error('Supabase unavailable');
    _skyAuthClient=window.supabase.createClient(SUPABASE_AUTH_URL,CFG.supabaseAnonKey,{auth:{persistSession:true,autoRefreshToken:true,detectSessionInUrl:true,flowType:'pkce',storageKey:'aimdojo.sky.auth'}});
    _skyAuthClient.auth.onAuthStateChange((_event,session)=>{ skyAcceptAuthSession(session); });
    const result=await _skyAuthClient.auth.getSession(); if(result.error) throw result.error; skyAcceptAuthSession(result.data&&result.data.session);
  }catch(error){ skySetStatus(T('saveSkyAuthUnavailable','SKY LINK UNAVAILABLE · PLAY STILL WORKS'),false); }
}
if(skySave.unknown) skySave.unknown.addEventListener('change',skySyncTimeUnknown);
if(skySave.lat) skySave.lat.addEventListener('input',skySyncCoordinatePair);
if(skySave.lon) skySave.lon.addEventListener('input',skySyncCoordinatePair);
if(skySave.form) skySave.form.addEventListener('input',()=>{ _skyFormDirty=true; });
if(skySave.authView) skySave.authView.addEventListener('submit',async e=>{
  e.preventDefault();
  if(_skyUiBusy) return;
  if(!_skyAuthClient){ skySetStatus(T('saveSkyAuthLoading','SKY LINK IS STILL WAKING…'),false); return; }
  if(!skySave.email||!skySave.email.value.trim()||!skySave.email.checkValidity()){ if(skySave.email) skySave.email.reportValidity(); return; }
  const email=skySave.email.value.trim(); skySetStatus(T('saveSkySending','SENDING PRIVATE SKY LINK…'),true);
  try{ const redirect=location.origin+location.pathname; const result=await _skyAuthClient.auth.signInWithOtp({email:email,options:{emailRedirectTo:redirect}}); if(result.error) throw result.error;
    skySetStatus(T('saveSkyCheckEmail','CHECK YOUR EMAIL · OPEN THE LINK IN THIS BROWSER · PLAY STILL WORKS'),false); showGhostToast('SKY LINK SENT');
  }catch(error){ const msg=skySoftFailure(error,'link'); skySetStatus(msg,false); showGhostToast(msg); }
});
if(skySave.form) skySave.form.addEventListener('submit',async e=>{
  e.preventDefault(); if(_skyUiBusy) return; skySyncTimeUnknown(); skySyncCoordinatePair(); if(!skySave.form.checkValidity()){ skySave.form.reportValidity(); return; }
  const ctl=ensureSkyProfileController(); if(!ctl||!_skyAuthSession){ skySetStatus(T('saveSkyExpired','SKY LINK EXPIRED · SIGN IN AGAIN'),false); return; }
  const raw={birth_date:skySave.date.value,birth_time:skySave.time.value,time_unknown:skySave.unknown.checked,tz:skySave.tz.value,place_label:skySave.place.value,lat:skySave.lat.value,lon:skySave.lon.value};
  const ticket=++_skyUiSeq; cancelSkyLinkedToast(); skySetStatus(T('saveSkySaving','SAVING CHART…'),true);
  try{ const pending=ctl.save(raw); renderSkyBriefUi(); const state=await pending; if(ticket!==_skyUiSeq) return; if(!state.hasChart) return; skyApplyControllerState(state,true); }
  catch(error){ if(ticket!==_skyUiSeq) return; const state=ctl.state; if(state&&state.lastSaveCommitted){ skyChatReset(); _personalListenExpected=true; if(_chartPackRank>=2) downgradePersonalSky(); if(_lsn&&_lsn.cache) _lsn.cache.clear(); if(state.profile) skyFillForm(state.profile,true); skySetStatus(SKY_MODE==='decorative'?T('saveSkyDecorative','CHART SAVED · DECORATIVE SKY ON'):T('saveSkySavedUnavailable','CHART SAVED · PERSONAL SKY UNAVAILABLE'),false); showGhostToast('CHART SAVED'); startTransitEssayFlow(); fetchSkyBriefForPause(); }
    else { const msg=skySoftFailure(error,'save'); skySetStatus(msg,false); showGhostToast(msg); } skyRenderAccount(true); if(state&&state.hasChart&&!state.lastSaveCommitted) fetchSkyBriefForPause(); }
});
if(skySave.clear) skySave.clear.addEventListener('click',async ()=>{
  if(_skyUiBusy) return; const ctl=ensureSkyProfileController(); if(!ctl||!_skyAuthSession) return; const ticket=++_skyUiSeq; cancelSkyLinkedToast(); skySetStatus(T('saveSkyClearing','CLEARING CHART…'),true);
  try{ const pending=ctl.clear(); renderSkyBriefUi(); await pending; if(ticket!==_skyUiSeq) return; _personalListenExpected=false; _skyChartEditing=false; skyChatReset(); transitEssayReset(); skyBriefReset(); if(_chartPackRank>=2) downgradePersonalSky(); skyClearForm(); skySetStatus(T('saveSkyCleared','CHART CLEARED'),false); skyRenderAccount(true); showGhostToast('CHART CLEARED'); }
  catch(error){ if(ticket!==_skyUiSeq) return; const msg=skySoftFailure(error,'clear'); skySetStatus(msg,false); showGhostToast(msg); if(ctl.state&&ctl.state.hasChart) fetchSkyBriefForPause(); }
});
if(skySave.edit) skySave.edit.addEventListener('click',()=>{ skyBeginChartEdit('edit'); });
if(skySave.newBtn) skySave.newBtn.addEventListener('click',()=>{ skyBeginChartEdit('new'); });
